-- ======================================================================
--  IRON LEAGUE — the leaderboard stops re-scoring the whole app
--
--  Paste the whole file into the Supabase SQL editor and press RUN, or apply
--  it over the API. Safe to run twice. Create-only: nothing changes shape,
--  nothing is dropped, NOTHING LOGGED IS TOUCHED and no points move. Every
--  number on every board is identical before and after.
--
--  GENERATED by tools/build_board_migration.py, which lifts both functions
--  below out of supabase/schema.sql. Edit there and re-run it, never here.
--
--  WHY
--  league_leaderboard() read life_scored_all(). That function has no WHERE
--  clause: it reads every workout ever logged, by anybody, in any league,
--  sorts the lot to dedupe the multi-league fan-out, and scores all of it.
--  The board then threw away every row but its own members'.
--
--  So one poll re-scored the entire app's history. The app polls every 25
--  seconds, per person with it open. Cost per poll grows with the app; polls
--  per minute grow with the app; the product of the two is what runs out of
--  CPU first -- well before the database runs out of room.
--
--  MEASURED, on a database seeded to 290 people with a year of training each
--  (49,300 workouts, 13 MB):
--
--    life_scored_all()        357 ms   <- the whole board, essentially
--    week_scored()              2.7 ms
--    week_combo_bonus()         2.7 ms
--    week_bounty_points()      11 ms
--
--  and the sort spilled to disk (654 temp blocks) on every single call.
--
--  THE FIX
--  life_scored_in(p_league) narrows the PEOPLE to that league's members --
--  never the leagues. A lifetime still counts what somebody logged
--  everywhere, which is why the filter is on profile_id and the
--  `distinct on (group_id)` dedup is untouched. The same board now costs
--  38 ms, and it scales with how many people are in the league rather than
--  with how big the app has become.
--
--  Proven identical to life_scored_all() for every member of every league in
--  supabase/test/board.sql. life_scored_all() stays: the control room still
--  wants everybody at once, and that page is read by one person, rarely.
--
--  A covering index on (group_id, league_id) was tried first and rejected:
--  at this scale it changed 370 ms into 345 ms and cost 4.4 MB. The problem
--  was never the dedup -- it was scoring 290 people to show 29.
-- ======================================================================
begin;
set local check_function_bodies = off;

-- -------------------------------------------------------- life_scored_in ---
create or replace function public.life_scored_in(p_league uuid)
returns table (profile_id uuid, points numeric)
language sql stable set search_path = public as $fn$
  with mine as (
    select m.profile_id from public.league_members m where m.league_id = p_league),
  one as (
    select distinct on (group_id)
           group_id, profile_id, week_start, exercise_key, points
    from public.workouts
    where profile_id in (select profile_id from mine)
    order by group_id, league_id),
  per as (select o.profile_id, o.week_start, o.exercise_key,
                 sum(o.points) as raw, max(x.cap) as cap
          from one o left join public.exercises x on x.key = o.exercise_key
          group by 1, 2, 3)
  select profile_id, sum(public.tier_points(raw, cap))::numeric
  from per group by 1
$fn$;

-- ---------------------------------------------------- league_leaderboard ---
create or replace function public.league_leaderboard(p_league uuid, p_week date default null)
returns table (profile_id uuid, display_name text, avatar text, points numeric,
               base_points numeric, bonus numeric, entries bigint,
               joined_at timestamptz, lifetime numeric, banner text,
               pinned_badges text[], name_color text)
language sql stable security definer set search_path = public as $fn$
  -- `lifetime` drives the rank banner on each row. Like divisions and duel
  -- records it is derived on read, so there is nothing to store or award.
  with wk as (select coalesce(p_week, public.current_week_start()) as w),
  cb as (select * from public.week_combo_bonus(p_league, (select w from wk))),
  bb as (select * from public.week_bounty_points(p_league, (select w from wk))),
  -- The week, already through the repetition discount of section 2b, so the
  -- board shows what a week is worth rather than what it was logged at.
  ws as (select * from public.week_scored(p_league, (select w from wk))),
  -- Lifetime follows the person, not the league, and is discounted the same
  -- way — week by week, so a year of training is never run through one curve.
  lt as (select * from public.life_scored_in(p_league))
  select p.id, p.display_name, p.avatar,
         (coalesce(ws.points, 0) + coalesce(cb.bonus, 0)
                                 + coalesce(bb.bounty, 0))::numeric,
         coalesce(ws.points, 0)::numeric,
         (coalesce(cb.bonus, 0) + coalesce(bb.bounty, 0))::numeric,
         coalesce(ws.entries, 0), m.joined_at,
         coalesce(lt.points, 0)::numeric, p.banner, p.pinned_badges,
         p.name_color
  from public.league_members m
  join public.profiles p on p.id = m.profile_id
  left join ws on ws.profile_id = p.id
  left join cb on cb.profile_id = p.id
  left join bb on bb.profile_id = p.id
  left join lt on lt.profile_id = p.id
  where m.league_id = p_league and public.is_member(p_league)
    and p.dormant_at is null
  order by 4 desc, 8 asc
$fn$;

-- -------------------------------------------------------- grants ---
revoke all on function public.league_leaderboard(uuid,date) from public, anon;
revoke all on function public.life_scored_in(uuid)          from public, anon, authenticated;
grant execute on function public.league_leaderboard(uuid,date) to authenticated;

commit;

